package run.ikaros.sharing; import java.time.Instant; import java.util.UUID; import org.springframework.stereotype.Service; import reactor.core.publisher.Flux; import reactor.core.publisher.Mono; import run.ikaros.common.NotFoundException; @Service public class PersistentRoomMessageService implements RoomMessageService{private final RoomRepository rooms;private final RoomMembershipRepository members;private final RoomMessageRepository messages;public PersistentRoomMessageService(RoomRepository r,RoomMembershipRepository m,RoomMessageRepository p){rooms=r;members=m;messages=p;}public Mono<RoomMessageView> send(UUID a,UUID roomId,SendRoomMessageRequest q){return access(a,roomId).flatMap(x->messages.findByRoomIdAndAuthorIdAndIdempotencyKey(roomId,a,q.idempotencyKey()).switchIfEmpty(Mono.defer(()->messages.save(new RoomMessageEntity(null,roomId,a,q.idempotencyKey(),q.body(),Instant.now(),null))))).map(this::view);}public Flux<RoomMessageView> list(UUID a,UUID roomId){return access(a,roomId).thenMany(messages.findAllByRoomIdOrderByCreatedAtAsc(roomId).map(this::view));}private Mono<Void> access(UUID a,UUID id){return rooms.findById(id).flatMap(r->members.findByRoomIdAndPrincipalId(id,a).filter(m->m.leftAt()==null).then()).switchIfEmpty(Mono.error(new NotFoundException("Room 不存在或无权访问")));}private RoomMessageView view(RoomMessageEntity m){return new RoomMessageView(m.id(),m.roomId(),m.authorId(),m.body(),m.createdAt());}}
